INSERT INTO campus_road_geometry (edge_id, geom, source, target, cost, reverse_cost)
SELECT edge.id,
       ST_SetSRID(ST_MakeLine(ST_MakePoint(src.x, src.z), ST_MakePoint(dst.x, dst.z)), 0),
       edge.from_node_id, edge.to_node_id,
       GREATEST(edge.distance, 0.1), GREATEST(edge.distance, 0.1)
FROM road_edge edge
JOIN road_node src ON src.id = edge.from_node_id
JOIN road_node dst ON dst.id = edge.to_node_id
WHERE edge.id >= 301;

